-- relies on the data seeded (and committed) by tenant_isolation.sql, which runs first
-- Probe: what can a PARENT (profile in school A, no linked child) execute? Informational; never fails the run.
reset role;
select set_config('request.jwt.claims','{"sub":"aaaaaaaa-2222-0000-0000-00000000000a","role":"authenticated"}',false);
set role authenticated;
create temp table probe_out(fn text, res text);
grant all on probe_out to authenticated;
do $$ declare n int; t text; begin begin execute $q$select count(*), left(string_agg(x::text,'|'),40) from (select * from public.account_balances()) x$q$ into n, t; insert into probe_out values ('account_balances','OK rows='||n||' '||coalesce(t,'')); exception when others then insert into probe_out values ('account_balances','err: '||left(sqlerrm,40)); end; end $$;
